head.b:skin:
/* ============================================================
   okluckday9009 · 모바일 우선 웹소설 블로그 테마 (ST011 · 노벨피아)
   배경 짙은 보라 — 대문에 주인공(표지·배너) 이미지
   색은 :root 의 변수만 바꾸면 전체가 바뀐다
   ============================================================ */
:root{
  --bg:#0f0b16;          /* 페이지 배경 */
  --panel:#181423;       /* 카드 */
  --soft:#221b31;        /* 서브 카드/칩 */
  --line:#332a46;        /* 테두리 */
  --ink:#f5f5f7;         /* 본문 글자 */
  --muted:#a1a1b5;       /* 보조 글자 */
  --gold:#f5c451;        /* 강조(금색) */
  --red:#e43a44;         /* CTA(빨강) */
  --purple:#8b5cf6;      /* 보라 */
  --radius:16px;
}
*{box-sizing:border-box}
html{scroll-behavior:smooth;-webkit-text-size-adjust:100%}
body{margin:0;background:var(--bg);color:var(--ink);
  font-family:'Noto Sans KR',system-ui,-apple-system,'Malgun Gothic',sans-serif;
  font-size:16px;line-height:1.7;word-break:keep-all;overflow-wrap:break-word}
a{color:inherit;text-decoration:none}
img{max-width:100%;height:auto;display:block}
iframe{max-width:100%;border:0}
#navbar-iframe{display:none}
.ok-skip{position:absolute;left:-9999px}
.ok-skip:focus{position:fixed;left:12px;top:12px;z-index:99;background:var(--gold);color:#100b16;
  padding:10px 14px;border-radius:10px;font-weight:700}

/* ── 상단바 (모바일은 가로 스크롤 칩) ─────────────────────── */
.ok-top{position:sticky;top:0;z-index:20;background:rgba(15,11,22,.94);
  backdrop-filter:blur(12px);border-bottom:1px solid var(--line)}
.ok-top__in{width:min(760px,100%);margin:0 auto;display:flex;align-items:center;
  gap:10px;padding:10px 14px}
.ok-brand{display:flex;align-items:center;gap:8px;font-weight:900;white-space:nowrap;font-size:15px}
.ok-brand i{display:grid;place-items:center;width:28px;height:28px;border-radius:9px;
  background:linear-gradient(135deg,var(--purple),var(--red));font-style:normal;font-size:15px}
.ok-nav{margin-left:auto;display:flex;gap:6px;overflow-x:auto;scrollbar-width:none;padding:2px}
.ok-nav::-webkit-scrollbar{display:none}
.ok-nav a{flex:0 0 auto;padding:7px 12px;border-radius:999px;background:var(--soft);
  border:1px solid var(--line);color:var(--muted);font-size:13px;font-weight:700}
.ok-nav a:hover,.ok-nav a:focus{color:#fff;border-color:var(--purple)}
.ok-nav a.ok-nav--cta{background:linear-gradient(135deg,var(--red),#ff6b6b);color:#fff;border-color:transparent}

/* ── 대문 (홈에서만) ──────────────────────────────────────── */
.ok-hero{position:relative}
.ok-hero__art{display:block;line-height:0}
.ok-hero__art img{width:100%;aspect-ratio:1600/864;object-fit:cover;object-position:center}
.ok-hero__art:after{content:'';position:absolute;left:0;right:0;bottom:0;height:38%;
  background:linear-gradient(180deg,rgba(15,11,22,0),var(--bg));pointer-events:none}
.ok-hero__card{width:min(760px,calc(100% - 28px));margin:-30px auto 0;position:relative;z-index:1;
  display:flex;gap:14px;padding:16px;background:linear-gradient(160deg,#1d1530,#140f20);
  border:1px solid var(--line);border-radius:var(--radius);
  box-shadow:0 18px 40px -20px rgba(0,0,0,.85)}
.ok-hero__cover{flex:0 0 92px;width:92px;border-radius:10px;border:1px solid var(--line);
  box-shadow:0 10px 24px -12px rgba(139,92,246,.65)}
.ok-hero__text{min-width:0}
.ok-eyebrow{margin:0 0 6px;color:var(--gold);font-size:11.5px;font-weight:900;letter-spacing:.14em}
.ok-title{margin:0 0 6px;font-size:20px;line-height:1.3;letter-spacing:-.02em;font-weight:900}
.ok-tags{margin:0 0 6px;color:var(--muted);font-size:12.5px}
.ok-desc{margin:0 0 12px;color:#cfc9dd;font-size:13.5px;line-height:1.6}
.ok-actions{display:flex;flex-wrap:wrap;gap:8px}
.ok-btn{display:inline-block;padding:11px 16px;border-radius:12px;font-weight:800;font-size:14px;
  border:1px solid transparent;transition:transform .12s}
.ok-btn:hover{transform:translateY(-1px)}
.ok-btn--red{background:linear-gradient(135deg,var(--red),#ff6b6b);color:#fff;
  box-shadow:0 10px 24px -12px rgba(228,58,68,.8)}
.ok-btn--gold{background:linear-gradient(135deg,var(--gold),#ffd97a);color:#140f20}
.ok-btn--ghost{background:transparent;border-color:var(--line);color:var(--ink)}

/* ── 대문 아래 이미지 메뉴 (유튜브 재생목록 · 노벨피아) ───────── */
.ok-menu{width:min(760px,calc(100% - 28px));margin:14px auto 0;
  display:grid;grid-template-columns:repeat(2,1fr);gap:10px}
.ok-menu__card{display:block;background:var(--panel);border:1px solid var(--line);
  border-radius:14px;overflow:hidden;min-width:0;transition:transform .12s}
.ok-menu__card:hover,.ok-menu__card:focus{transform:translateY(-2px);border-color:var(--purple)}
.ok-menu__card img{width:100%;aspect-ratio:16/9;object-fit:cover;display:block}
.ok-menu__body{display:block;padding:10px 12px 12px}
.ok-menu__body b{display:block;font-size:13.5px;line-height:1.35}
.ok-menu__body i{display:block;margin-top:3px;font-style:normal;font-size:11.5px;color:var(--muted)}
.ok-chips{width:min(760px,calc(100% - 28px));margin:10px auto 0;display:flex;gap:8px;
  overflow-x:auto;scrollbar-width:none;padding:2px}
.ok-chips::-webkit-scrollbar{display:none}
.ok-chips a{flex:0 0 auto;padding:8px 13px;border-radius:999px;background:var(--soft);
  border:1px solid var(--line);font-size:12.5px;font-weight:700;color:var(--muted)}
.ok-chips a:hover,.ok-chips a:focus{color:#fff;border-color:var(--gold)}

/* ── 본문/글 카드 (Blogger 기본 글 마크업 기준) ──────────────── */
.ok-main{width:min(760px,calc(100% - 28px));margin:18px auto 40px}
.ok-feed__title{margin:6px 0 12px;font-size:13px;letter-spacing:.14em;color:var(--muted);font-weight:900}
.post-outer-container,.post-outer{margin:0 0 16px}
.post{background:var(--panel);border:1px solid var(--line);border-radius:var(--radius);
  padding:16px 14px;box-shadow:0 12px 30px -22px rgba(0,0,0,.9)}
.post-title{margin:0 0 6px;font-size:18px;line-height:1.4;font-weight:900;letter-spacing:-.01em}
.post-title a{color:#fff}
.post-title a:hover{color:var(--gold)}
.post-header,.post-footer{color:var(--muted);font-size:12.5px}
.post-header{margin:0 0 10px;display:flex;gap:8px;flex-wrap:wrap;align-items:center}
.post-body{font-size:15.5px;color:#e9e6f2}
.post-body p{margin:0 0 14px}
.post-body iframe{width:100%;aspect-ratio:16/9;height:auto;border-radius:12px}
.post-body table{width:100%;border-collapse:collapse}
.post-body td,.post-body th{border:1px solid var(--line);padding:6px 8px;font-size:13px}
.post-labels{margin:12px 0 0;display:flex;flex-wrap:wrap;gap:6px}
.post-labels a,.post-labels .label-holder{background:var(--soft);border:1px solid var(--line);
  border-radius:999px;padding:4px 10px;font-size:12px;color:var(--muted)}
.post-comment-link,.post-timestamp{font-size:12.5px;color:var(--muted)}
.jump-link{color:var(--gold);font-size:13px;font-weight:700}
.feed-links,.blog-feeds,.home-link{display:none}

/* 페이지 이동 */
.blog-pager{display:flex;justify-content:center;gap:10px;margin:18px 0 0;flex-wrap:wrap}
.blog-pager a{padding:11px 18px;border-radius:12px;background:var(--soft);border:1px solid var(--line);
  font-weight:800;font-size:14px;color:var(--ink)}
.blog-pager a:hover{border-color:var(--purple)}

/* 댓글 */
#comments{background:var(--panel);border:1px solid var(--line);border-radius:var(--radius);
  padding:16px 14px;margin:16px 0 0}
.comments .comment-thread{margin:0}
#comments h4{margin:0 0 12px;font-size:15px}
.comment{border-top:1px solid var(--line);padding:10px 0}
.comment .comment-block{background:var(--soft);border-radius:12px;padding:10px 12px}

/* 푸터 */
.ok-foot{border-top:1px solid var(--line);background:#0c0812;padding:26px 14px 40px;text-align:center}
.ok-foot__novel{margin:0 0 12px;color:var(--muted);font-size:13.5px}
.ok-foot__novel b{color:var(--ink)}
.ok-foot__btns{display:flex;gap:8px;justify-content:center;flex-wrap:wrap;margin:0 0 14px}
.ok-foot__meta{margin:0;color:#6f6a82;font-size:12px}

/* 넓은 화면(데스크톱)에서도 가운데 정렬 */
@media(min-width:768px){
  .ok-title{font-size:26px}
  .ok-hero__cover{flex:0 0 120px;width:120px}
  .ok-desc{font-size:15px}
  .post{padding:22px 24px}
  .post-title{font-size:21px}
  .ok-menu__body b{font-size:15px}
  .ok-menu__body i{font-size:12.5px}
}
@media(max-width:420px){
  .ok-menu{gap:8px}
  .ok-menu__body{padding:8px 10px 10px}
  .ok-menu__body b{font-size:12.5px}
  .ok-hero__card{padding:14px;gap:12px}
}
